vector<vector<int>> levelOrder(TreeNode* root) {
vector<vector<int>> res;
if (root == NULL) return res;
queue<TreeNode*> q;
q.push(root);
while (!q.empty()) {
int sz = q.size(); // size of the current level, snapshot it
vector<int> level;
for (int i = 0; i < sz; i++) {
TreeNode* node = q.front();
q.pop();
level.push_back(node->val);
if (node->left) q.push(node->left);
if (node->right) q.push(node->right);
}
res.push_back(level);
}
return res;
}
Why int sz = q.size() must come before the loop
During the inner loop you are pushing children, so q.size() keeps changing. If you write for
(int i = 0; i < q.size(); i++) the condition is re-evaluated every iteration and you will happily
consume the next level too, producing one giant level. Take the snapshot once. This is the single most
common BFS bug.
