int best = 0; // the global answer
int height(TreeNode* root) { // returns only the height
if (root == NULL) return 0;
int L = height(root->left);
int R = height(root->right);
best = max(best, L + R); // update the answer at this node
return 1 + max(L, R); // hand only the height upward
}
