The O(N) solution
Use Part 6. Do one postorder pass. Each call returns only the height , and along the way it updates a
shared best answer.
class Solution {
int best = 0;
int height(TreeNode* root) {
if (root == NULL) return 0;
int L = height(root->left);
int R = height(root->right);
best = max(best, L + R); // the path that turns HERE
return 1 + max(L, R); // what my parent can use
}
public:
int diameterOfBinaryTree(TreeNode* root) {
best = 0; // reset, LeetCode reuses the object
height(root);
return best;
}
};
