Balanced template
int check(TreeNode* r) { // height, or -1 if unbalanced
if (!r) return 0;
int L = check(r->left); if (L == -1) return -1;
int R = check(r->right); if (R == -1) return -1;
if (abs(L - R) > 1) return -1;
return 1 + max(L, R);
}
